//! `:help` / `Space ?` buffer decoration (0088 §2, U10): the help text is
//! generated by editor/help.rs in the keymap's curated section order;
//! here its rows get house style — one accent, the keycap idiom over the
//! key column, section rules in the faint border ink, unavailable rows
//! muted italic — through the same typed-decoration pattern the git
//! surfaces use (0010 §5), never a special-purpose renderer fork. The
//! spans' concatenated content keeps the buffer line's exact bytes, so
//! search, yank and the caret keep reading the real buffer.

use ratatui::style::{Modifier, Style};
use ratatui::text::Span;

use super::style::Tokens;

/// The generator's row shape: two spaces, the key column (padded to the
/// section's widest key plus one cell each side), two spaces, the
/// description. The key column is the keycap.
pub(crate) const KEY_INDENT: &str = "  ";
pub(crate) const COLUMN_GAP: &str = "  ";
/// Section rules read `─ Title ─────`.
pub(crate) const RULE: &str = "─ ";

pub(crate) fn row_spans(t: &Tokens, text: &str, width: u16) -> Vec<Span<'static>> {
    if text.starts_with("strop ") {
        // the header: name bold, the rest quiet
        let (name, rest) = text.split_at(text.find(" · ").unwrap_or(text.len()));
        return vec![
            Span::styled(
                name.to_string(),
                Style::default().fg(t.text).add_modifier(Modifier::BOLD),
            ),
            Span::styled(rest.to_string(), Style::default().fg(t.muted)),
        ];
    }
    if let Some(rest) = text.strip_prefix(RULE) {
        let title_end = rest.find(" ─").unwrap_or(rest.len());
        let (title, rule) = rest.split_at(title_end);
        let used = text.chars().count();
        let pad = (width as usize).saturating_sub(used);
        return vec![
            Span::styled(RULE.to_string(), Style::default().fg(t.faint)),
            Span::styled(
                title.to_string(),
                Style::default().fg(t.text).add_modifier(Modifier::BOLD),
            ),
            Span::styled(
                format!("{rule}{}", "─".repeat(pad)),
                Style::default().fg(t.faint),
            ),
        ];
    }
    let planned = text.ends_with("(soon)");
    let body = if planned {
        Style::default().fg(t.muted).add_modifier(Modifier::ITALIC)
    } else {
        Style::default().fg(t.text)
    };
    // binding rows: `  <keys padded>  <desc>` — the key column ends at the
    // first double space after the indent
    let Some(rest) = text.strip_prefix(KEY_INDENT) else {
        return vec![Span::styled(text.to_string(), body)];
    };
    // the padding run after the keys ends two cells before the description
    let split = rest.find(COLUMN_GAP).map(|start| {
        let run_end = rest[start..]
            .find(|c: char| c != ' ')
            .map_or(rest.len(), |offset| start + offset);
        (run_end - COLUMN_GAP.len(), run_end)
    });
    match split {
        Some((keys_end, desc_start)) if keys_end > 0 && desc_start < rest.len() => {
            let keys = &rest[..keys_end];
            let desc = &rest[desc_start..];
            let cap = if planned {
                Style::default().fg(t.muted).bg(t.raised)
            } else {
                Style::default()
                    .fg(t.accent)
                    .bg(t.raised)
                    .add_modifier(Modifier::BOLD)
            };
            vec![
                Span::styled(KEY_INDENT.to_string(), Style::default()),
                Span::styled(keys.to_string(), cap),
                Span::styled(COLUMN_GAP.to_string(), Style::default()),
                Span::styled(desc.to_string(), body),
            ]
        }
        _ => vec![Span::styled(text.to_string(), body)],
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tokens() -> Tokens {
        Tokens::new(strop_core::theme::ThemeId::Hone)
    }

    #[test]
    fn rows_keep_their_bytes_and_wear_one_accent() {
        let t = tokens();
        let joined = |spans: &[Span<'static>]| -> String {
            spans.iter().map(|span| span.content.as_ref()).collect()
        };
        let header = row_spans(&t, "strop 0.54.0 · help · / search · q close", 60);
        assert!(joined(&header).starts_with("strop 0.54.0 · help"));
        assert_eq!(header[0].style.fg, Some(t.text));

        let rule = row_spans(&t, "─ Moving ──", 40);
        assert!(joined(&rule).starts_with("─ Moving ──"));
        assert_eq!(rule[1].content, "Moving");
        assert_eq!(rule[0].style.fg, Some(t.faint));
        assert_eq!(rule[1].style.fg, Some(t.text));

        let row = row_spans(&t, "   space f    files", 40);
        assert_eq!(joined(&row), "   space f    files");
        assert_eq!(row[1].content, " space f  ");
        assert_eq!(row[1].style.fg, Some(t.accent));
        assert_eq!(row[1].style.bg, Some(t.raised));
        assert_eq!(row[3].style.fg, Some(t.text));

        let soon = row_spans(&t, "   space j    jumplist picker  (soon)", 40);
        assert!(soon.iter().all(|span| span.style.fg != Some(t.accent)));
        assert!(soon[3].style.add_modifier.contains(Modifier::ITALIC));
    }
}
